import test, { after } from 'node:test';
import { register } from 'node:module';
import { MessageChannel } from 'node:worker_threads';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { soloPage, memoryStorage, settle } from './helpers/solo-dom.mjs';
import { waitFor as waitForStage } from './helpers/wait-for.mjs';
import { audioHarness } from './helpers/soundtrack-audio.mjs';
import { fixture, memoryIndexedDB, structuralProbe } from './helpers/soundtrack-fixtures.mjs';
import { createSoundtrackStore } from '../soundtrack-store.mjs';
import { createManagedMediaStore } from '../managed-media-store.mjs';
import { prepareSoundtrackLibrary } from '../soundtrack-bundle.mjs';
import { BUILTIN_SOUNDTRACK_TRACKS } from '../soundtrack.mjs';
import { SOUNDTRACK_CATALOGUE } from '../content/soundtrack-catalogue.mjs';
import { ONLINE_SOUNDTRACK_CATALOGUE_URL } from '../online-soundtrack-catalogue.mjs';
import { publicCatalogueResponse } from './helpers/soundtrack-public-catalogue.mjs';
import { AUDIO_PREFERENCES_KEY } from '../audio-preferences.mjs';
import { emptyLibrary, updatePreferences, saveLibrary, loadLibrary } from '../library.mjs';
import { retryFixture } from './fixtures/retry-scenarios.mjs';

const { port1, port2 } = new MessageChannel();
const importGates = new Map();
let importGateSequence = 0;
port1.on('message', (message) => {
  const gate = importGates.get(message.id);
  if (!gate) return;
  if (message.type === 'entered') gate.entered++;
  if (message.type === 'released') gate.released += message.count;
  if (message.type === 'ack') gate.acknowledged.add(message.action);
});
register(new URL('./helpers/soundtrack-authoring-loader.mjs', import.meta.url), {
  data: { channel: port2 },
  transferList: [port2],
});
after(() => {
  port1.postMessage({ action: 'dispose' });
  port1.close();
});
async function holdAuthoringImport(t) {
  const id = ++importGateSequence;
  const state = { entered: 0, released: 0, acknowledged: new Set() };
  const actions = [];
  let page = null;
  importGates.set(id, state);
  function diagnostic(stage) {
    const text = (value) => String(value ?? '').slice(0, 160);
    const element = (name) => page?.$(name);
    t.diagnostic(
      JSON.stringify({
        stage,
        gate: {
          id,
          entered: state.entered,
          released: state.released,
          acknowledged: [...state.acknowledged],
        },
        actions: actions.map((action) => ({
          label: action.label,
          settled: action.settled,
          failed: action.failed,
          error: action.failed ? text(action.error?.message ?? action.error) : null,
        })),
        page: page
          ? {
              hidden: page.doc.hidden,
              active: page.doc.activeElement?.id ?? null,
              flight: page.doc.body.dataset.flightState ?? null,
              studioOpen: element('soundtrack-dialog')?.open ?? null,
              studioConnected: element('soundtrack-dialog')?.isConnected ?? null,
              closeDisabled: element('soundtrack-close')?.disabled ?? null,
              tracksConnected: element('soundtrack-tracks')?.isConnected ?? null,
              status: text(element('soundtrack-status')?.textContent),
              authoring: text(element('soundtrack-authoring-status')?.textContent),
              errors: page.errors.slice(0, 4).map((error) => text(error?.message ?? error)),
            }
          : null,
      }),
    );
  }
  async function waiting(stage, predicate, { pump = false } = {}) {
    try {
      if (pump) await settle(predicate, stage, { timeoutMs: 5000 });
      else await waitForStage(predicate, { message: stage, timeoutMs: 5000 });
    } catch (error) {
      diagnostic(stage);
      throw error;
    }
  }
  function observe(promise, label) {
    const action = { label, settled: false, failed: false, error: null, value: undefined };
    actions.push(action);
    void Promise.resolve(promise).then(
      (value) => {
        action.value = value;
        action.settled = true;
      },
      (error) => {
        action.error = error;
        action.failed = true;
        action.settled = true;
      },
    );
    return action;
  }
  async function join(action, stage = action.label) {
    await waiting(stage, () => action.settled);
    if (action.failed) {
      diagnostic(stage);
      throw action.error;
    }
    return action.value;
  }
  const send = async (action, fail = false) => {
    state.acknowledged.delete(action);
    port1.postMessage({ action, id, fail });
    await waiting(
      'authoring gate ' + action + ' acknowledgement',
      () => state.acknowledged.has(action),
      { pump: true },
    );
  };
  let released = false;
  const release = async (fail = false) => {
    if (released) return;
    released = true;
    await send('release', fail);
  };
  t.after(async () => {
    const failures = [];
    try {
      await release();
    } catch (error) {
      failures.push(error);
    }
    for (const action of actions) {
      try {
        await join(action, 'cleanup: ' + action.label);
      } catch (error) {
        failures.push(error);
      }
    }
    importGates.delete(id);
    if (failures.length === 1) throw failures[0];
    if (failures.length > 1) throw new AggregateError(failures, 'Authoring action cleanup failed.');
  });
  await send('hold');
  return {
    state,
    release,
    observe,
    join,
    waiting,
    attach: (value) => {
      page = value;
    },
  };
}

const classes = JSON.parse(readFileSync(new URL('../content/classes.json', import.meta.url)));
const base = retryFixture('self-contact').level;
const campaign = {
  version: 'xonix-campaign.v1',
  id: 'soundtrack-host',
  revision: '1',
  title: 'Music host journey',
  classRecipes: classes,
  levels: [1, 2].map((number) => ({
    ...base,
    id: `music-map-${number}`,
    name: `Music map ${number}`,
    goal: { coverage: 0.1 },
    rules: { lives: 3 },
  })),
};
const profileKey = 'revealline.library.dev.v1';
const preferences = (page) =>
  loadLibrary(page.storage, profileKey, { campaigns: [campaign] }).library.preferences;
const ticks = (page, count) => {
  for (let i = 0; i < count; i++) page.frame();
};
async function startFlight(page) {
  const button = page.$('start-button'),
    action = button.onclick;
  assert.equal(typeof action, 'function', 'Start exposes its existing host action.');
  let pending = null,
    calls = 0;
  button.onclick = (...args) => {
    calls++;
    pending = action.apply(button, args);
    return pending;
  };
  try {
    button.click();
    assert.equal(calls, 1, 'Start invokes the existing host action exactly once.');
    if (page.doc.body.dataset.flightState !== 'running') {
      assert.equal(
        typeof pending?.then,
        'function',
        'Fresh Start returns its real visual preparation operation.',
      );
      await pending;
    }
    assert.equal(page.doc.body.dataset.flightState, 'running');
  } catch (error) {
    const preparation = page.$('flight-preparation-status');
    error.message +=
      '\n' +
      JSON.stringify({
        flightState: page.doc.body.dataset.flightState ?? null,
        pictureState: page.doc.body.dataset.pictureState ?? null,
        start: page.$('start-button').textContent,
        preparation: {
          hidden: preparation.hidden,
          state: preparation.dataset.state ?? null,
          stage: preparation.dataset.stage ?? null,
          text: preparation.textContent,
        },
        runMessage: page.$('run-message').textContent,
        saveWarning: page.$('save-warning').textContent,
        openDialogs: page.doc.querySelectorAll('dialog[open]').map((dialog) => dialog.id),
        errors: page.errors.map((value) => String(value?.stack ?? value)),
      });
    throw error;
  } finally {
    button.onclick = action;
  }
}
async function waitFor(predicate, label) {
  for (let i = 0; i < 100; i++) {
    if (predicate()) return;
    await new Promise((resolve) => setTimeout(resolve, 5));
  }
  assert.ok(predicate(), label);
}
async function setup(
  t,
  {
    filePlayback = true,
    audioPreferences = {},
    emptyMusic = false,
    fetchResponse,
    publicStyles,
    creatorSource,
    browserSetup,
  } = {},
) {
  const original = await fixture(),
    db = memoryIndexedDB(),
    store = createSoundtrackStore({ indexedDB: db.indexedDB, soundtrackCatalogue: !!publicStyles });
  const library = {
    ...original.library,
    tracks: original.library.tracks.map((track) =>
      creatorSource === undefined
        ? track
        : { ...track, rights: { ...track.rights, source: creatorSource } },
    ),
    playlists: [
      {
        ...original.library.playlists[0],
        trackIds: [original.track.id, BUILTIN_SOUNDTRACK_TRACKS[0].id],
      },
    ],
    selection: { playlistId: 'qa.mix' },
  };
  const prepared = await prepareSoundtrackLibrary(library, original.assets, {
    probeMedia: structuralProbe,
  });
  if (!emptyMusic) await store.commit(prepared, { expectedGeneration: 0, publicStyles });
  store.close();
  const audio = {
    ...audioHarness(),
    durationSeconds: original.track.asset.durationSeconds,
    filePlayback,
  };
  const storage = memoryStorage();
  saveLibrary(
    storage,
    profileKey,
    updatePreferences(emptyLibrary(), { musicEnabled: false, ...audioPreferences }),
  );
  const page = await soloPage(t, {
    campaign,
    storage,
    audio,
    soundtrackIndexedDB: db.indexedDB,
    fetchResponse,
    browserSetup,
  });
  if (filePlayback)
    await settle(() => !page.$('soundtrack-open').disabled, 'Real soundtrack host initialized');
  return { page, audio, db, original };
}

for (const zeroVolume of [false, true]) {
  test(`silent Solo Start defers native audio until ${zeroVolume ? 'volume rises' : 'unmute'} in its control gesture`, async (t) => {
    let constructions = 0;
    const { page, audio } = await setup(t, {
      audioPreferences: { musicEnabled: zeroVolume, masterVolume: zeroVolume ? 0 : 0.8 },
      browserSetup({ globals }) {
        const create = globals.AudioContext;
        globals.AudioContext = function () {
          constructions++;
          return create();
        };
      },
    });
    assert.equal(constructions, 0);
    page.$('start-button').click();
    await settle(() => page.doc.body.dataset.flightState === 'running', 'Silent flight starts');
    assert.equal(constructions, 0, 'Muted gameplay never opens a native audio device.');
    if (zeroVolume) page.change('master-volume', '0.5');
    else page.$('sound-button').click();
    assert.equal(
      constructions,
      1,
      'Native activation occurs synchronously in the control gesture.',
    );
    await settle(() => audio.context.state === 'running', 'Unmuted audio resumes');
    assert.equal(page.doc.body.dataset.flightState, 'running');
    assert.deepEqual(page.errors, []);
  });
}

test('deferred Solo activation preserves an explicit music Pause when master sound is restored', async (t) => {
  let constructions = 0;
  const { page, audio } = await setup(t, {
    browserSetup({ globals }) {
      const create = globals.AudioContext;
      globals.AudioContext = function () {
        constructions++;
        return create();
      };
    },
  });
  page.$('start-button').click();
  await settle(() => page.doc.body.dataset.flightState === 'running', 'Silent flight starts');
  assert.equal(constructions, 0);
  await openStudio(page);
  await page.$('soundtrack-pause').onclick();
  const plays = page.audioElements.map((media) => media.plays);
  assert.equal(constructions, 0);
  page.$('soundtrack-master-mute').click();
  assert.equal(constructions, 1);
  await settle(() => audio.context.state === 'running', 'Effects activate');
  assert.deepEqual(
    page.audioElements.map((media) => media.plays),
    plays,
  );
  assert.equal(musicMedia(page).paused, true);
  assert.equal(page.$('solo-quick-music-settings-toggle').textContent, 'Play music');
  assert.deepEqual(page.errors, []);
});

const onlineRecordingHash = 'a'.repeat(64);
function onlineCatalogueResponse(status = 200) {
  const source = {
    format: 'revealline-public-soundtrack-catalogue.v1',
    archive: {
      id: 'revealline-soundtracks',
      baseURL: 'https://mekhovov.github.io/revealline-soundtracks/',
    },
    sources: [],
    counts: { declaredTracks: 1, uniqueRecordings: 1, duplicateAliases: 0, audioBytes: 1234 },
    tracks: [
      {
        id: 'fixture.recording',
        title: 'Metadata-only fixture recording',
        artist: 'Test fixture',
        durationSeconds: 12,
        tags: ['ambient'],
        source: 'https://creator.example/fixture',
        license: 'CC BY 4.0 International',
        licenseURL: 'https://creativecommons.org/licenses/by/4.0/',
        credit: 'Synthetic catalogue metadata fixture, no recording supplied.',
        fileName: 'fixture.mp3',
        archiveId: 'fixture-album',
        collection: 'Fixture album',
        collections: ['Fixture album'],
        status: 'licensed-preview',
        listeningApproval: 'not-reviewed',
        gameCatalogueAdmission: false,
        contentId: false,
        recordingModeEligible: true,
        audio: {
          path: `https://github.com/mekhovov/revealline-soundtracks/releases/download/audio-test/${onlineRecordingHash}.mp3`,
          bytes: 1234,
          sha256: onlineRecordingHash,
        },
        aliases: [],
      },
    ],
  };
  const response = new Response(JSON.stringify(source), {
    status,
    headers: { 'Content-Type': 'application/json' },
  });
  // Node's synthetic Response has no URL; the real catalogue requires a direct,
  // exact-URL HTTP response and reads its bounded stream before admitting it.
  Object.defineProperty(response, 'url', { value: ONLINE_SOUNDTRACK_CATALOGUE_URL });
  return response;
}

test('muted fresh Solo browses metadata only on Studio demand and acquires no recordings before Play', async (t) => {
  assert(
    SOUNDTRACK_CATALOGUE.tracks.some((track) => track.archiveId),
    'This edition has admitted online music.',
  );
  const requests = [];
  const { page } = await setup(t, {
    emptyMusic: true,
    fetchResponse: async (url) => {
      requests.push(String(url));
      if (String(url) === ONLINE_SOUNDTRACK_CATALOGUE_URL) return onlineCatalogueResponse();
    },
  });
  await waitFor(
    () => !page.$('soundtrack-summary').textContent.includes('Loading music library'),
    'Silent library preparation settles',
  );
  assert.deepEqual(
    requests.filter((url) => url === ONLINE_SOUNDTRACK_CATALOGUE_URL),
    [],
    'The hidden panel does not request public metadata',
  );
  assert.equal(page.$(`soundtrack-online-play-${onlineRecordingHash}`), null);
  assert(page.audioElements.every((media) => media.plays === 0));
  await openStudio(page);
  await waitForPublicCatalogue(page, onlineRecordingHash);
  assert.deepEqual(
    requests.filter((url) => url === ONLINE_SOUNDTRACK_CATALOGUE_URL),
    [ONLINE_SOUNDTRACK_CATALOGUE_URL],
  );
  assert.equal(
    requests.some((url) => /\.mp3(?:$|[?#])/.test(url)),
    false,
    'Silent catalogue discovery must not acquire recording bytes.',
  );
  assert(page.audioElements.every((media) => media.plays === 0));
  assert.deepEqual(page.errors, []);
});

test('failed explicit Audio catalogue metadata is reported and Studio retries it once without acquiring recordings', async (t) => {
  const requests = [];
  let metadataRequests = 0;
  const { page } = await setup(t, {
    emptyMusic: true,
    fetchResponse: async (url) => {
      requests.push(String(url));
      if (String(url) === ONLINE_SOUNDTRACK_CATALOGUE_URL)
        return onlineCatalogueResponse(++metadataRequests === 1 ? 503 : 200);
    },
  });
  await waitFor(
    () => !page.$('soundtrack-summary').textContent.includes('Loading music library'),
    'Silent library preparation settles',
  );
  assert.equal(metadataRequests, 0, 'The hidden panel does not browse the public catalogue');
  assert(page.audioElements.every((media) => media.plays === 0));
  page.$('settings-button').click();
  page.$('settings-tab-audio').click();
  assert.equal(page.$('settings-panel-audio').hidden, false);
  await waitFor(
    () =>
      /unavailable/i.test(page.$('soundtrack-online-status').textContent) &&
      !page.$('soundtrack-online-reload').disabled,
    'The explicit Audio visit reports and settles its rejected metadata request',
  );
  assert.equal(metadataRequests, 1);
  assert.equal(page.$(`soundtrack-online-play-${onlineRecordingHash}`), null);
  page.doc.querySelector('[data-close="settings-dialog"]').click();
  await openStudio(page);
  await waitForPublicCatalogue(page, onlineRecordingHash);
  assert.deepEqual(
    requests.filter((url) => url === ONLINE_SOUNDTRACK_CATALOGUE_URL),
    [ONLINE_SOUNDTRACK_CATALOGUE_URL, ONLINE_SOUNDTRACK_CATALOGUE_URL],
  );
  assert.equal(
    requests.some((url) => /\.mp3(?:$|[?#])/.test(url)),
    false,
  );
  assert(page.audioElements.every((media) => media.plays === 0));
  assert.deepEqual(page.errors, []);
});
async function openStudio(page) {
  page.$('settings-button').click();
  assert.equal(page.$('settings-dialog').open, true);
  page.$('settings-tab-audio').click();
  assert.equal(page.$('settings-panel-audio').hidden, false);
  page.$('soundtrack-open').click();
  await waitFor(
    () =>
      page.$('soundtrack-dialog')?.open &&
      page.$('soundtrack-tracks')?.isConnected &&
      /Saved library loaded|Music library ready|unsaved draft/.test(
        page.$('soundtrack-status')?.textContent,
      ),
    'Actual studio opens, reads the local library and mounts authoring controls',
  );
  assert.equal(page.$('settings-dialog').open, false);
}
async function waitForPublicCatalogue(page, hash = '1'.repeat(64)) {
  await waitFor(
    () =>
      !!page.$(`soundtrack-online-play-${hash}`) && !page.$('soundtrack-online-reload').disabled,
    'The requested catalogue is admitted and its panel reader has settled',
  );
}
const musicMedia = (page) => page.audioElements[0];
async function playStudio(page) {
  const play = page.$('soundtrack-play');
  assert.equal(play.disabled, false);
  // Prepared media starts before the Studio action finishes its host notification.
  await play.onclick();
  await waitFor(() => musicMedia(page).paused === false, page.$('soundtrack-now').textContent);
}
function leaveStudio(page) {
  page.$('soundtrack-close').click();
  assert.equal(page.$('settings-dialog').open, true);
  page.doc.querySelector('[data-close="settings-dialog"]').click();
  page.frame(0);
}

test('Settings music text follows master immediately and remains coherent after transport notifications', async (t) => {
  const { page } = await setup(t);
  page.$('settings-button').click();
  page.$('settings-tab-audio').click();
  await page.$('music-preview').onclick();
  const media = musicMedia(page);
  assert.equal(media.paused, false);
  assert.equal(media.muted, true);
  assert.equal(page.$('music-preview').textContent, 'Playlist playing · master sound muted');
  media.currentTime = 0.015;
  const before = { src: media.src, time: media.currentTime, plays: media.plays };
  for (const muted of [false, true]) {
    page.$('settings-master-mute').click();
    const label = muted ? 'Playlist playing · master sound muted' : 'Soundtrack playing ♫';
